1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	};
5	
6	export type Scenario = {
7	  customer: { yearsWithMHPCO: number };
8	  steps: { op: string; items: Item[] }[];
9	};
10	
11	export type ScenarioResult = {
12	  results: { premium: number }[];
13	};
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
24	const CURSE_SURCHARGE_PERCENT = 50;
25	const PROCESSING_FEE = 5;
26	
27	const percentOf = (amount: number, percent: number): number =>
28	  (amount * percent) / 100;
29	
30	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
31	
32	const BLOCK_SIZE = 3;
33	const BLOCK_BASE_PREMIUM = 60;
34	
35	const countByType = (items: Item[]): Map<string, number> =>
36	  items.reduce(
37	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
38	    new Map<string, number>(),
39	  );
40	
41	const formsBuildingBlock = (count: number): boolean => count === BLOCK_SIZE;
42	
43	const basePremiumForAlikeItems = (type: string, count: number): number =>
44	  formsBuildingBlock(count)
45	    ? BLOCK_BASE_PREMIUM
46	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
47	
48	const policyBasePremium = (items: Item[]): number =>
49	  [...countByType(items)]
50	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
51	    .reduce((total, alikeItemsPremium) => total + alikeItemsPremium, 0);
52	
53	const curseSurcharge = (items: Item[]): number =>
54	  items
55	    .filter((item) => item.cursed)
56	    .reduce(
57	      (surcharge, item) =>
58	        surcharge +
59	        percentOf(BASE_PREMIUM_BY_ITEM_TYPE[item.type], CURSE_SURCHARGE_PERCENT),
60	      0,
61	    );
62	
63	const quotePremium = (items: Item[]): number => {
64	  const basePremium = policyBasePremium(items);
65	  const total =
66	    basePremium +
67	    curseSurcharge(items) +
68	    percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) +
69	    PROCESSING_FEE;
70	  return roundInMHPCOsFavour(total);
71	};
72	
73	export const runScenario = (scenario: Scenario): ScenarioResult => ({
74	  results: scenario.steps.map((step) => ({
75	    premium: quotePremium(step.items),
76	  })),
77	});
