const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_ITEM_TYPE[item.type];

/**
 * An item-specific modifier: a percentage of the AFFECTED ITEM's own base
 * premium, charged only for items the rule applies to.
 */
type ItemSurcharge = { appliesTo: (item: Item) => boolean; percent: number };

const ITEM_SURCHARGES: ItemSurcharge[] = [
  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
];

