  ITEM_SURCHARGES.filter(({ appliesTo }) => appliesTo(item)).reduce(
    (surcharge, { percent }) => surcharge + percentOf(itemBasePremium(item), percent),
    0,
  );

const itemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurcharge(item), 0);

const quotePremium = (items: Item[]): number => {
  const basePremium = policyBasePremium(items);
  return roundInMHPCOsFavour(
    basePremium +
      itemSurcharges(items) +
      percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) +
      PROCESSING_FEE,
  );
};

