/**
 * Item-specific modifiers are percentages of the AFFECTED ITEM's own base
 * premium — unlike policy-wide modifiers, which apply to the policy base.
 */
const surchargePercentFor = (item: Item): number =>
  item.cursed ? CURSE_SURCHARGE_PERCENT : 0;

const itemSurcharges = (items: Item[]): number =>
  items.reduce(
    (total, item) =>
      total + percentOf(itemBasePremium(item), surchargePercentFor(item)),
    0,
  );
